<?php
use App\Models\{Ticket,Project};
use App\Services\{Query,Filter};
$pauseProject=Project::save(['name'=>'Pause de test','key'=>'PA'.strtoupper(bin2hex(random_bytes(3)))]);
$pauseId=Ticket::create($pauseProject,['title'=>'Obstacle puis pause','description'=>'Conserver le contexte','status'=>'progress','flagged'=>1,'progress_percent'=>37,'estimated_hours'=>'2.5','start_date'=>'2026-11-02','due_date'=>'2026-11-06','labels'=>'urgent, test'],$uid);
$beforePause=Ticket::find($pauseId);
check(Query::count($pauseProject,['flagged'=>1])===1,'un ticket bloqué reste dans les vues actives');
Ticket::setPaused($pauseId,true,$uid,$beforePause['version']);$pausedTicket=Ticket::find($pauseId);
check($pausedTicket['status']==='paused' && $pausedTicket['paused_from_status']==='progress','pause mémorise l’état précédent');
$preserved=array_flip(['title','description','flagged','progress_percent','estimated_hours','start_date','due_date','labels','assignee_id','team_id','parent_id']);
check(array_intersect_key($beforePause,$preserved)===array_intersect_key($pausedTicket,$preserved),'pause conserve informations dates heures avancement et blocage');
check(Query::count($pauseProject,[])===0 && Query::tickets($pauseProject,[])===[],'pause exclue des recherches de travail par défaut');
check(Query::count($pauseProject,['pause'=>'only'])===1,'filtre des tickets en pause');
check(Query::count($pauseProject,['pause'=>'all'])===1,'inclusion explicite des pauses');
check(Query::count($pauseProject,['status'=>'paused'])===1,'état En pause explicite retrouve le ticket');
check(Query::count($pauseProject,['jql'=>'status = "En pause"'])===1,'recherche avancée en français retrouve les pauses');
check(Query::count($pauseProject,['jql'=>'title ~ "pause"'])===0,'recherche textuelle avancée garde les pauses masquées');
check(Query::count($pauseProject,['jql'=>'status IN (paused, todo)'])===1,'recherche avancée mixte inclut les pauses demandées');
check(Query::count($pauseProject,['jql'=>'status = PAUSED'])===1,'état de pause en majuscules normalisé à la frontière du filtre');
check(Filter::active(['pause'=>'only']) && Filter::active(['pause'=>'all']) && !Filter::active([]),'pause reconnue comme filtre actif');
rejects(fn()=>Filter::where($pauseProject,['pause'=>['only']]),'filtre de pause ambigu refusé');
rejects(fn()=>Ticket::setPaused($pauseId,false,$uid,$beforePause['version']),'reprise avec ancienne version refusée');
Ticket::setPaused($pauseId,true,$uid,$pausedTicket['version']);
check(Ticket::find($pauseId)['version']===$pausedTicket['version'],'pause répétée ne modifie pas le ticket');
Ticket::patch($pauseId,['description'=>'Contexte précisé'],$uid,$pausedTicket['version']);$pausedTicket=Ticket::find($pauseId);
check($pausedTicket['paused_from_status']==='progress','modification pendant une pause conserve l’état de reprise');
Ticket::setPaused($pauseId,false,$uid,$pausedTicket['version']);$resumed=Ticket::find($pauseId);
check($resumed['status']==='progress' && $resumed['paused_from_status']===null && Query::count($pauseProject,[])===1,'reprise retrouve son état et sa visibilité');
$initialPause=Ticket::create($pauseProject,['title'=>'Plus tard','status'=>'paused'],$uid);$initial=Ticket::find($initialPause);
Ticket::setPaused($initialPause,false,$uid,$initial['version']);
check(Ticket::find($initialPause)['status']==='todo','ticket créé en pause reprend à faire');
Ticket::archive($pauseId,true,$uid,$resumed['version']);$archivedPause=Ticket::find($pauseId);
rejects(fn()=>Ticket::setPaused($pauseId,true,$uid,$archivedPause['version']),'pause d’un ticket archivé refusée');
